"""Consolidate R0 evidence without turning unqualified observations into timing claims."""
from pathlib import Path
import json,hashlib
N=Path(__file__).resolve().parent
read=lambda name:json.loads((N/name).read_text())
boundary=read('current-boundary/summary.json');work=read('r0-work-model.json');tail=read('call-cost/tail-comparison.json');phases=read('phase-repeat/summary.json');calls=read('call-cost/summary.json');paired=read('call-cost-paired/summary.json');gates=read('intermediate-gates.json');source=read('source-verification.json')
