slow=[x for run in tail['runs'] for x in run['tails'] if 'observed_call_counts' in x]
assert len(slow)==3 and all(x['source_calls']==440 and x['callback_calls']==11938 and x['observed_call_counts']['fstat']==4199 and x['observed_call_counts']['crc32']==21577 and x['major_faults']==0 for x in slow)
result={'status':'R0 accepted on qualified coarse attribution and causal work-count validation; fine-grained timing remains unresolved', 'frozen_source':source,'qualified_boundaries':boundary,'current_work':work,'registered_intermediate_gates':gates,'slow_query_selected_work':{'qualifying_samples':len(slow),'source_calls':440,'callbacks':11938,'fstat':4199,'crc32':21577,'major_faults':0,'limitations':'Selected counts do not cover all work or CPU instructions; observer failed timing-quality gate, and sample timing cannot be used to estimate component shares.'},'rejected_timing_evidence':['phase-repeat/summary.json','call-cost/summary.json','call-cost-paired/summary.json','current-phases/receipt.json'],'kuzu_profile':{'zyx_candidates':225000,'kuzu_scan_output_tuples':105000,'input_ratio':225000/105000,'note':'Post-only profile outputs zero for the same predicate. Row reduction is observed; pruning implementation is unknown. Profile timings are not formal benchmark timings.'},'model':{'formula':'1 / (1-f+f/s), when only the measured exclusive supply boundary is changed','all_node_supply_f':boundary[0]['exclusive_source_elapsed_share'],'all_node_if_supply_2x':1/(1-boundary[0]['exclusive_source_elapsed_share']/2),'all_node_if_supply_removed':1/(1-boundary[0]['exclusive_source_elapsed_share']),'interpretation':'Measured supply is the largest qualified boundary, not a demonstrated removable amount. Callback-only elimination is too small to reach the 1.5x intermediate gate. A qualifying candidate must reduce additional source and/or outside-source work.'},'candidate_hypotheses':['Use snapshot-valid predicate pruning to skip provably nonmatching blocks and preserve exact fallback semantics.','Fuse scan, block authentication, typed columns and filtering to reduce repeated group/page work and per-cell materialization; verify actual work reductions, do not assume them.','For multi-key grouping, validate per-row PMR string-key allocations, then evaluate typed composite-key lookup with safe semantics and budgets.'],'carried_risks':['A credible breakdown of the largest removable cost inside and outside the source boundary remains missing; both repeat observers failed preregistered gates.','The three slow queries repeat selected work counts, but uncounted instructions versus execution-speed changes are unresolved.','The allocation experiment validates real persisted read data only; updated-data lifecycle and complete block-path proof remain R1/R3 obligations.'],'scope':'R0 attribution plus bounded key-scratch experiment. R1 block architecture has not started. No performance acceptance claim.'}
experiment=read('key-scratch/experiment-receipt.json')
assert experiment['tests']==37 and experiment['failures']==0 and experiment['allocation_reduction']==99380
result['causal_work_experiment']=experiment
result['accepted_progress_percent']=10
result['acceptance_basis']='Freeze, qualified source boundary, deterministic work, Kuzu input comparison, tail investigation, explicit rejected evidence, preregistered gates and a causal allocation-elimination experiment are complete. Fine-grained timing is a carried uncertainty, not fabricated or waived from final acceptance.'
(N/'r0-attribution-summary.json').write_text(json.dumps(result,indent=2)+'\n');print(result['status'])
